"""Append-only administrative record entries (PRD 2.4)."""

from flask import g

import db

# Entries generated by a cascade rather than by the direct request are SYSTEM
# entries and carry a null actor_user_id (PRD 2.4).
SYSTEM_CODES = {"CLASSIFICATION_ESCALATED", "DOCUMENT_SUPERSEDED", "DECISION_VACATED"}


def add_entry(action, entry_code, related_entity_type, related_entity_ref, summary):
    highest = 0
    for entry in db.db["record_entries"].values():
        if entry["action_id"] == action["id"] and entry["sequence_no"] > highest:
            highest = entry["sequence_no"]
    system = entry_code in SYSTEM_CODES
    row = db.new_row(
        "record_entries",
        {
            "action_id": action["id"],
            "sequence_no": highest + 1,
            "entry_code": entry_code,
            "occurred_at": db.logical_iso(),
            "actor_role": "SYSTEM" if system else g.role,
            "actor_user_id": None if system else g.user_id,
            "summary": summary,
            "related_entity_type": related_entity_type,
            "related_entity_ref": related_entity_ref,
        },
        common=False,
    )
    action["record_entry_count"] = sum(
        1 for e in db.db["record_entries"].values() if e["action_id"] == action["id"]
    )
    db.touch(action)
    return row


def entries_for(action_id):
    rows = [e for e in db.db["record_entries"].values() if e["action_id"] == action_id]
    return sorted(rows, key=lambda e: e["sequence_no"])
